  1→'use client';
  2→
  3→import { useState, useMemo, useEffect, useRef } from 'react';
  4→import { ProjectCard } from './ProjectCard';
  5→import { ProjectAdapter } from '@/lib/perception/adapter';
  6→import { VisitorArchetype } from '@/lib/perception/types';
  7→import type { Project } from '@/lib/projects';
  8→import type { PerceptionState } from '@/lib/perception/types';
  9→
 10→interface ProjectGridProps {
 11→  projects: Project[];
 12→  allDisciplines: string[];
 13→  perceptionState?: PerceptionState | null;
 14→}
 15→
 16→export function ProjectGrid({ projects, allDisciplines, perceptionState }: ProjectGridProps) {
 17→  const [activeDiscipline, setActiveDiscipline] = useState<string | null>(null);
 18→
 19→  // State to hold the displayed project order (frozen during browsing)
 20→  const [displayedProjects, setDisplayedProjects] = useState<Project[]>(projects);
 21→
 22→  // Track whether we've applied adaptation this session
 23→  const hasAppliedAdaptation = useRef(false);
 24→
 25→  /**
 26→   * INVISIBLE SHUFFLE STRATEGY:
 27→   * - Perception learns silently while user browses
 28→   * - Projects remain in same order (no live reordering)
 29→   * - When component mounts (user returns from project page), apply the adaptation
 30→   * - User experiences: "The grid shuffled while I was away!"
 31→   */
 32→  useEffect(() => {
 33→    // Only apply adaptation once per component mount
 34→    if (
 35→      !hasAppliedAdaptation.current &&
 36→      perceptionState &&
 37→      perceptionState.profile.archetype !== VisitorArchetype.UNKNOWN
 38→    ) {
 39→      const adapted = ProjectAdapter.adaptProjectOrder(projects, perceptionState.profile.archetype);
 40→      setDisplayedProjects(adapted);
 41→      hasAppliedAdaptation.current = true;
 42→    }
 43→  }, [perceptionState, projects]);
 44→
 45→  // Filter projects based on active discipline (single-select)
 46→  const filteredProjects = useMemo(() => {
 47→    if (!activeDiscipline) return displayedProjects;
 48→
 49→    return displayedProjects.filter(project => {
 50→      return project.disciplines.includes(activeDiscipline);
 51→    });
 52→  }, [displayedProjects, activeDiscipline]);
 53→
 54→  const handleDisciplineClick = (discipline: string) => {
 55→    // Toggle: click same discipline to deselect
 56→    setActiveDiscipline(prev => prev === discipline ? null : discipline);
 57→  };
 58→
 59→  const clearFilters = () => {
 60→    setActiveDiscipline(null);
 61→  };
 62→
 63→  return (
 64→    <div className="space-y-8">
 65→      {/* Filter bar temporarily hidden */}
 66→      {false && (
 67→        <div className="pb-6">
 68→          <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4">
 69→            {/* Discipline filters - Two rows */}
 70→            <div>
 71→              <div className="flex flex-col gap-3">
 72→                {/* First row: EVERYTHING, LIGHTING, COMMISSIONS */}
 73→                <div className="flex flex-wrap gap-4 md:gap-6">
 74→                  {allDisciplines.slice(0, 3).map(discipline => (
 75→                    <button
 76→                      key={discipline}
 77→                      onClick={() => handleDisciplineClick(discipline)}
 78→                      className="text-xs md:text-sm transition-all duration-200"
 79→                      style={{
 80→                        color: activeDiscipline === discipline ? '#000000' : '#6a6a6a',
 81→                        fontFamily: 'var(--font-lora)',
 82→                        fontWeight: activeDiscipline === discipline ? 700 : 600,
 83→                        letterSpacing: '0.06em'
 84→                      }}
 85→                    >
 86→                      {discipline}
 87→                    </button>
 88→                  ))}
 89→                </div>
 90→                {/* Second row: DIRECTION, EXPERIMENTAL, R&D */}
 91→                <div className="flex flex-wrap gap-4 md:gap-6">
 92→                  {allDisciplines.slice(3).map(discipline => (
 93→                    <button
 94→                      key={discipline}
 95→                      onClick={() => handleDisciplineClick(discipline)}
 96→                      className="text-xs md:text-sm transition-all duration-200"
 97→                      style={{
 98→                        color: activeDiscipline === discipline ? '#000000' : '#6a6a6a',
 99→                        fontFamily: 'var(--font-lora)',
100→                        fontWeight: activeDiscipline === discipline ? 700 : 600,
101→                        letterSpacing: '0.06em'
102→                      }}
103→                    >
104→                      {discipline}
105→                    </button>
106→                  ))}
107→                </div>
108→              </div>
109→            </div>
110→
111→            {/* Clear filters */}
112→            {activeDiscipline && (
113→              <button
114→                onClick={clearFilters}
115→                className="text-sm text-neutral-500 hover:text-black transition-colors whitespace-nowrap md:ml-auto"
116→              >
117→                clear ×
118→              </button>
119→            )}
120→          </div>
121→
122→          {/* Active filter count */}
123→          {activeDiscipline && (
124→            <p className="text-sm text-neutral-500 mt-4">
125→              {filteredProjects.length} {filteredProjects.length === 1 ? 'project' : 'projects'} found
126→            </p>
127→          )}
128→        </div>
129→      )}
130→
131→      {/* Grid Pattern: 1 hero → all remaining in 2-column grid */}
132→      <div className="space-y-12">
133→        {filteredProjects.map((project, index) => {
134→          // Only first project is hero, all others are grid items
135→          const isHero = index === 0;
136→
137→          if (isHero) {
138→            // Full-width hero (first project only)
139→            return (
140→              <ProjectCard
141→                key={project.id}
142→                project={project}
143→              />
144→            );
145→          }
146→
147→          if (index === 1) {
148→            // Start of grid - collect all remaining projects
149→            const gridProjects = filteredProjects.slice(1);
150→            return (
151→              <div key="grid-all" className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
152→                {gridProjects.map(gridProject => (
153→                  <ProjectCard
154→                    key={gridProject.id}
155→                    project={gridProject}
156→                  />
157→                ))}
158→              </div>
159→            );
160→          }
161→
162→          // Skip - already rendered as part of grid
163→          return null;
164→        })}
165→      </div>
166→
167→      {/* No results */}
168→      {filteredProjects.length === 0 && (
169→        <div className="text-center py-16">
170→          <p className="text-neutral-500">No projects found with selected filters.</p>
171→          <button
172→            onClick={clearFilters}
173→            className="mt-4 text-sm text-black hover:opacity-70 transition-opacity"
174→          >
175→            Clear filters
176→          </button>
177→        </div>
178→      )}
179→    </div>
180→  );
181→}
