  1→'use client';
  2→
  3→import Link from 'next/link';
  4→import { VideoThumbnail } from './VideoThumbnail';
  5→import type { Project } from '@/lib/projects';
  6→
  7→/**
  8→ * TENDRIL-STYLE PROJECT CARD
  9→ *
 10→ * Design philosophy:
 11→ * - Titles always visible below thumbnail (scan-friendly)
 12→ * - Video plays on hover (motion draws attention)
 13→ * - Clean typography hierarchy: title → description → client
 14→ * - Description first: leads with thinking, not credits
 15→ * - Client as footnote: credibility signal, not headline
 16→ * - No category tags - let the visuals speak
 17→ */
 18→
 19→interface ProjectCardProps {
 20→  project: Project;
 21→  isHero?: boolean;
 22→}
 23→
 24→export function ProjectCard({ project }: ProjectCardProps) {
 25→  const aspectRatio = '16/9';
 26→
 27→  return (
 28→    <article
 29→      className="group relative w-full project-card"
 30→      data-project-slug={project.slug}
 31→    >
 32→      {/* Video Thumbnail Container - Clean, no overlays */}
 33→      <Link
 34→        href={`/projects/${project.slug}`}
 35→        className="block relative w-full overflow-hidden project-thumbnail"
 36→        data-project-slug={project.slug}
 37→        style={{ borderRadius: 'var(--radius-md)' }}
 38→      >
 39→        <VideoThumbnail
 40→          videoId={project.videoId}
 41→          videoHash={project.videoHash}
 42→          aspectRatio={aspectRatio}
 43→          startTime={project.startTime}
 44→          isCinematic={project.isCinematic}
 45→          thumbnail={project.thumbnail}
 46→        />
 47→      </Link>
 48→
 49→      {/* Title + Client - Always visible below thumbnail */}
 50→      <Link
 51→        href={`/projects/${project.slug}`}
 52→        className="block group-hover:opacity-60"
 53→        style={{
 54→          paddingTop: 'var(--space-xs)',
 55→          transition: 'opacity var(--transition-base)'
 56→        }}
 57→      >
 58→        <h3
 59→          style={{
 60→            color: 'var(--text-primary)',
 61→            fontWeight: 400,
 62→            fontFamily: 'var(--font-lora)',
 63→            fontStyle: 'italic',
 64→            letterSpacing: '0.01em',
 65→            fontSize: 'clamp(22px, 2.2vw, 28px)',
 66→            lineHeight: 1.25,
 67→            marginBottom: project.gridDescription || project.client ? 'var(--space-tiny)' : 0
 68→          }}
 69→        >
 70→          {project.title}
 71→        </h3>
 72→
 73→        {/* Description - readable but clearly secondary to title */}
 74→        {project.gridDescription ? (
 75→          <p
 76→            style={{
 77→              color: 'var(--grey-500)',
 78→              fontFamily: 'var(--font-open-sans)',
 79→              fontWeight: 400,
 80→              fontSize: '17px',
 81→              lineHeight: 1.95,
 82→              marginBottom: project.client ? 'var(--space-tiny)' : 0
 83→            }}
 84→          >
 85→            {project.gridDescription}
 86→          </p>
 87→        ) : null}
 88→
 89→        {/* Client as footnote - dimmest, true metadata */}
 90→        {project.client ? (
 91→          <p
 92→            style={{
 93→              color: 'var(--text-dim)',
 94→              fontFamily: 'var(--font-display)',
 95→              fontWeight: 500,
 96→              fontSize: '11px',
 97→              letterSpacing: '0.12em',
 98→              textTransform: 'uppercase'
 99→            }}
100→          >
101→            {project.client}
102→          </p>
103→        ) : null}
104→      </Link>
105→    </article>
106→  );
107→}
