 1→/**
 2→ * Vimeo Utilities
 3→ * - Shared player loader (deduplicates dynamic import across 5 components)
 4→ * - API metadata fetcher
 5→ */
 6→
 7→// Re-export the Player type for components
 8→export type { default as VimeoPlayerType } from '@vimeo/player';
 9→
10→// Cached import promise — ensures only one network request for the chunk
11→let cachedPlayerImport: Promise<typeof import('@vimeo/player')> | null = null;
12→
13→/**
14→ * Load the Vimeo Player constructor via dynamic import.
15→ * Deduplicates across all callers — the chunk is fetched once.
16→ */
17→export function loadVimeoPlayer() {
18→  if (!cachedPlayerImport) {
19→    cachedPlayerImport = import('@vimeo/player');
20→  }
21→  return cachedPlayerImport.then(m => m.default);
