  9→
 10→/**
 11→ * GOLDEN RATIO LADDER GRID - SCROLL-DRIVEN ARCADE
 12→ *
 13→ * Animation: Scroll-linked arcade flicker/pulse
 14→ * - Scroll position = animation progress
 15→ * - Scroll speed = animation speed
 16→ * - Reversible - scroll up and cards fade back out
 17→ * - Like dashboard gauges powering on as you scan across them
 18→ */
 19→
 20→interface LadderGridProps {
 21→  projects: Project[];
 22→}
 23→
 24→const COLUMN_GAP = 89;
 25→const ROW_GAP = 89;
 26→const CARD_GAP = 144;
 27→
 28→// Shared scroll state across all card instances
 29→// This ensures all cards respond consistently to "scroll up from bottom"
 30→let globalHasReachedBottom = false;
 31→let globalScrollingUpFromBottom = false;
 32→let globalLastScrollY = 0;
 33→
 34→/**
 35→ * SIMPLE FADE-UP (Original Style, Scroll-Driven)
 36→ * ───────────────────────────────────────────────
 37→ * Mimics the original CSS fadeUp animation:
 38→ *   opacity: 0 → 1
 39→ *   translateY: 24px → 0
 40→ *   ease-out timing
 41→ *
 42→ * Clean. Simple. No flicker. Just a reveal.
 43→ */
 44→function easeOut(t: number): number {
 45→  // Cubic ease-out: fast start, gentle arrival
 46→  return 1 - Math.pow(1 - t, 3);
 47→}
 48→
 49→function getRevealValues(progress: number): { opacity: number; brightness: number; y: number } {
 50→  const p = Math.max(0, Math.min(1, progress));
 51→  const eased = easeOut(p);
 52→
 53→  return {
 54→    opacity: eased,           // 0 → 1
 55→    brightness: 1,            // constant (no brightness manipulation)
 56→    y: 24 * (1 - eased),      // 24px → 0px
 57→  };
 58→}
 59→
 60→function ScrollAnimatedCard({ project }: { project: Project }) {
 61→  const ref = useRef<HTMLDivElement>(null);
 62→  const prefersReducedMotion = usePrefersReducedMotion();
 63→  const rafRef = useRef<number>(0);
 64→
 65→  // Per-card: track the maximum progress achieved (for "lock on" behavior)
 66→  const maxProgressRef = useRef(0);
 67→
 68→  useEffect(() => {
 69→    const element = ref.current;
 70→    if (!element || prefersReducedMotion) return;
 71→
 72→    const updateAnimation = () => {
 73→      const rect = element.getBoundingClientRect();
 74→      const viewportHeight = window.innerHeight;
 75→      const scrollY = window.scrollY;
 76→      const docHeight = document.documentElement.scrollHeight;
 77→
 78→      // === GLOBAL SCROLL STATE DETECTION ===
 79→      // Detect if we've scrolled to the bottom of the page
 80→      const atBottom = (scrollY + viewportHeight) >= (docHeight - 150);
 81→      if (atBottom) {
 82→        globalHasReachedBottom = true;
 83→      }
 84→
 85→      // Detect scroll direction change after reaching bottom
 86→      // If scrolling UP after hitting bottom, enable reversal
 87→      if (globalHasReachedBottom && scrollY < globalLastScrollY - 50) {
 88→        globalScrollingUpFromBottom = true;
 89→      }
 90→
 91→      // If scrolling back DOWN, disable reversal mode
 92→      if (globalScrollingUpFromBottom && scrollY > globalLastScrollY + 30) {
 93→        globalScrollingUpFromBottom = false;
 94→      }
 95→
 96→      // Reset "reached bottom" if user scrolls back to top area
 97→      if (scrollY < viewportHeight) {
 98→        globalHasReachedBottom = false;
 99→        globalScrollingUpFromBottom = false;
100→      }
101→
102→      globalLastScrollY = scrollY;
103→
104→      // === PER-CARD PROGRESS CALCULATION ===
105→      // Simple fade-up: enters viewport → settles at 30% from top
106→      const startY = viewportHeight;
107→      const endY = viewportHeight * 0.3;
108→
109→      // Calculate raw progress based on scroll position
110→      const currentY = rect.top;
111→      let rawProgress: number;
112→
113→      if (currentY >= startY) {
114→        rawProgress = 0;
115→      } else if (currentY <= endY) {
116→        rawProgress = 1;
117→      } else {
118→        rawProgress = (startY - currentY) / (startY - endY);
119→      }
120→
121→      // === LOCK/UNLOCK LOGIC ===
122→      // Normal: cards lock at their max progress (only get MORE visible)
123→      // After hitting bottom + scrolling up: cards can reverse
124→      let progress: number;
125→
126→      if (globalScrollingUpFromBottom) {
127→        // User is scrolling up from bottom - allow reversal
128→        progress = rawProgress;
129→        maxProgressRef.current = rawProgress;
130→      } else {
131→        // Normal scrolling - cards can only become MORE visible
132→        maxProgressRef.current = Math.max(maxProgressRef.current, rawProgress);
133→        progress = maxProgressRef.current;
134→      }
135→
136→      const values = getRevealValues(progress);
137→
138→      // Directly update DOM for performance (no React re-render)
139→      element.style.opacity = String(values.opacity);
140→      element.style.transform = `translateY(${values.y}px)`;
141→    };
142→
143→    const onScroll = () => {
144→      cancelAnimationFrame(rafRef.current);
145→      rafRef.current = requestAnimationFrame(updateAnimation);
146→    };
147→
148→    // Initial calculation
149→    updateAnimation();
150→
151→    window.addEventListener('scroll', onScroll, { passive: true });
152→    window.addEventListener('resize', updateAnimation, { passive: true });
153→
154→    return () => {
155→      window.removeEventListener('scroll', onScroll);
156→      window.removeEventListener('resize', updateAnimation);
157→      cancelAnimationFrame(rafRef.current);
158→    };
159→  }, [prefersReducedMotion]);
160→
161→  // Reduced motion: simple visibility based on viewport
162→  if (prefersReducedMotion) {
163→    return (
164→      <div ref={ref} style={{ opacity: 1 }}>
165→        <ProjectCard project={project} />
166→      </div>
167→    );
168→  }
169→
170→  return (
171→    <div
172→      ref={ref}
173→      style={{
174→        opacity: 0,
175→        transform: 'translateY(24px)',
176→        willChange: 'opacity, transform',
177→        contentVisibility: 'auto',
178→        containIntrinsicSize: '0 400px',
179→      }}
180→    >
181→      <ProjectCard project={project} />
182→    </div>
183→  );
184→}
