186→export function LadderGrid({ projects }: LadderGridProps) {
187→  const { isMobile } = useIsMobile();
188→
189→  // Reset module-level scroll state on unmount (prevents stale state across navigations/HMR)
190→  useEffect(() => {
191→    return () => {
192→      globalHasReachedBottom = false;
193→      globalScrollingUpFromBottom = false;
194→      globalLastScrollY = 0;
195→    };
196→  }, []);
197→
198→  const { leftColumn, rightColumn } = useMemo(() => {
199→    const left: Project[] = [];
200→    const right: Project[] = [];
201→    for (let i = 0; i < projects.length; i++) {
202→      (i % 2 === 0 ? left : right).push(projects[i]);
203→    }
204→    return { leftColumn: left, rightColumn: right };
205→  }, [projects]);
206→
207→  return (
208→    <VideoThumbnailManager>
209→      <div className="relative">
210→        <div
211→          className="grid grid-cols-1 md:grid-cols-2"
212→          style={{
213→            columnGap: `${COLUMN_GAP}px`,
214→            rowGap: `${ROW_GAP}px`
215→          }}
216→        >
217→          <div
218→            className="flex flex-col"
219→            style={{ gap: `${CARD_GAP}px` }}
220→          >
221→            {leftColumn.map((project) => (
222→              <ScrollAnimatedCard
223→                key={project.id}
224→                project={project}
225→              />
226→            ))}
227→          </div>
228→
229→          <div
230→            className="flex flex-col md:mt-[38.2%]"
231→            style={{ gap: `${CARD_GAP}px` }}
232→          >
233→            {rightColumn.map((project) => (
234→              <ScrollAnimatedCard
235→                key={project.id}
236→                project={project}
237→              />
238→            ))}
239→          </div>
240→        </div>
241→      </div>
242→    </VideoThumbnailManager>
243→  );
244→}
