234→.project-card:nth-child(4) { animation-delay: 240ms; }
235→.project-card:nth-child(5) { animation-delay: 320ms; }
236→.project-card:nth-child(6) { animation-delay: 400ms; }
237→
238→@keyframes fadeIn {
