346→/* ===========================================
347→   VIEW TRANSITIONS - Cinematic Page Crossfades
348→   =========================================== */
349→
350→/*
351→ * Design philosophy:
352→ * - Film dissolve feel, not flashy web animation
353→ * - Content: subtle crossfade with micro-scale for depth
354→ * - Navigation: fade only (no scale/position change - stays anchored)
355→ * - Duration: 500ms content, 400ms nav (slow enough to feel intentional)
356→ * - Easing: ease-in-out for cinematic linear-ish blend
357→ */
358→
359→/* Dark canvas behind all transition layers — prevents white bleed-through */
360→::view-transition {
361→  background-color: #141414;
362→}
363→
364→::view-transition-group(root),
365→::view-transition-group(navigation),
366→::view-transition-group(footer) {
367→  background-color: #141414;
368→}
369→
370→/* Root (main content) transition */
371→::view-transition-old(root),
372→::view-transition-new(root) {
373→  animation-duration: 500ms;
374→  animation-timing-function: ease-in-out;
375→}
376→
377→/* Old page: fade out with slight scale down */
378→::view-transition-old(root) {
379→  animation-name: fade-and-scale-out;
380→}
381→
382→/* New page: fade in with slight scale up */
383→::view-transition-new(root) {
384→  animation-name: fade-and-scale-in;
385→}
386→
387→@keyframes fade-and-scale-out {
388→  from {
389→    opacity: 1;
390→    transform: scale(1);
391→  }
392→  to {
393→    opacity: 0;
394→    transform: scale(0.98);
395→  }
396→}
397→
398→@keyframes fade-and-scale-in {
399→  from {
400→    opacity: 0;
401→    transform: scale(1.02);
402→  }
403→  to {
404→    opacity: 1;
405→    transform: scale(1);
406→  }
407→}
408→
409→/* Navigation: fade only, no scale (stays anchored) */
410→::view-transition-old(navigation),
411→::view-transition-new(navigation) {
412→  animation-duration: 400ms;
413→  animation-timing-function: ease-in-out;
414→}
415→
416→::view-transition-old(navigation) {
417→  animation-name: fade-out-only;
418→}
419→
420→::view-transition-new(navigation) {
421→  animation-name: fade-in-only;
422→}
423→
424→/* Hero reel: fade only, no scale (prevents white flash from iframe reinit) */
425→/* Dark background on the transition group prevents white bleed-through during crossfade */
426→::view-transition-group(hero-reel) {
427→  background-color: #141414;
428→}
429→
430→::view-transition-old(hero-reel),
431→::view-transition-new(hero-reel) {
432→  animation-duration: 400ms;
433→  animation-timing-function: ease-in-out;
434→}
435→
436→::view-transition-old(hero-reel) {
437→  animation-name: fade-out-only;
438→}
439→
440→::view-transition-new(hero-reel) {
441→  animation-name: fade-in-only;
442→}
443→
444→/* Footer: fade only, no scale (stays anchored) */
445→::view-transition-old(footer),
446→::view-transition-new(footer) {
447→  animation-duration: 400ms;
448→  animation-timing-function: ease-in-out;
449→}
450→
451→::view-transition-old(footer) {
452→  animation-name: fade-out-only;
453→}
454→
455→::view-transition-new(footer) {
456→  animation-name: fade-in-only;
457→}
458→
459→@keyframes fade-out-only {
460→  from { opacity: 1; }
461→  to { opacity: 0; }
462→}
463→
464→@keyframes fade-in-only {
465→  from { opacity: 0; }
466→  to { opacity: 1; }
467→}
468→
469→/* Respect reduced motion */
470→@media (prefers-reduced-motion: reduce) {
471→  ::view-transition-old(root),
472→  ::view-transition-new(root),
473→  ::view-transition-old(navigation),
474→  ::view-transition-new(navigation),
475→  ::view-transition-old(hero-reel),
476→  ::view-transition-new(hero-reel),
477→  ::view-transition-old(footer),
478→  ::view-transition-new(footer) {
479→    animation: none !important;
480→  }
481→}
